//#region src/main/tencent-docs/prewarm-scheduler.ts
/**
* Tencent Docs engine prewarm 调度器
*
* 背景：daemon 冷启动完成后，业务侧希望预热本地 tencent-docs 引擎（editor_sdk），
* 让 agent-spawn / 用户第一次打开文档预览时不再等待 spawn。
*
* 但预热本身会占用磁盘 IO + CPU + Windows Defender 扫描资源，与 renderer 首屏
* 渲染争抢。原方案在 daemon 就绪后立即 fire-and-forget，实测 daemon.start
* 端到端和 renderer React 首绘会相互拖累。
*
* 本模块把预热触发时机改为：
*   1. 等 renderer 首屏 render 完（通过 IPC 信号）
*   2. 或者到达超时兜底（20s）
* 二者以先到者为准，且用 signal 保证只触发一次。
*
* IPC 信号约定：renderer 在 React root mount + Adapter+Auth ready 后
* 通过 `renderer:signalStartupFirstPaint` invoke 一次即可。
*/
/** renderer → main 首屏就绪信号 IPC 通道 */
var RENDERER_STARTUP_FIRST_PAINT_CHANNEL = "renderer:signalStartupFirstPaint";
/**
* 兜底超时：即使 renderer 从未发出信号（首屏挂了、崩了、window 未创建），
* 也在 20s 后强制 kick prewarm，避免"预热永不发生"。
* 20s 是相对 daemon 就绪的偏移，给正常首屏留足时间（用户 2 实测二次启动
* 5.8s 首绘、首次启动 12.8s 首绘）。
*/
var PREWARM_FALLBACK_TIMEOUT_MS = 2e4;
/**
* 注册 renderer 首屏信号 IPC + fallback timer，任一先到即触发一次 prewarm。
*
* 幂等：多次收到 renderer 信号只 kick 一次（用户切换窗口、reload 页面等场景）。
*/
function schedulePrewarmOnFirstPaint(options) {
	const ipc = options.ipc ?? electron.ipcMain;
	const fallbackMs = options.fallbackTimeoutMs ?? PREWARM_FALLBACK_TIMEOUT_MS;
	let kicked = false;
	let disposed = false;
	const kickOnce = (source) => {
		if (kicked || disposed) return;
		kicked = true;
		options.logger?.info?.(`[TencentDocsPrewarm] kick source=${source}`);
		try {
			options.kick(source);
		} catch (error) {
			options.logger?.warn?.("[TencentDocsPrewarm] kick threw synchronously (should not happen):", error instanceof Error ? error.message : String(error));
		}
		cleanupResources();
	};
	const cleanupResources = () => {
		if (fallbackTimer) {
			clearTimeout(fallbackTimer);
			fallbackTimer = void 0;
		}
		try {
			ipc.removeHandler(RENDERER_STARTUP_FIRST_PAINT_CHANNEL);
		} catch {}
	};
	ipc.handle(RENDERER_STARTUP_FIRST_PAINT_CHANNEL, async () => {
		kickOnce("renderer-first-paint");
		return { ok: true };
	});
	let fallbackTimer = setTimeout(() => {
		options.logger?.info?.(`[TencentDocsPrewarm] renderer signal did not arrive within ${fallbackMs}ms, fallback kick`);
		kickOnce("daemon-background-prewarm-fallback");
	}, fallbackMs);
	fallbackTimer.unref?.();
	return { dispose() {
		if (disposed) return;
		disposed = true;
		cleanupResources();
	} };
}
//#endregion
//#region src/main/startup-steps/first-screen-rendered-signal.ts
/** 兜底超时：这么久还没收到首屏渲染信号就强制放行等待方 + 转发 daemon，避免永久挂起。 */
var FIRST_SCREEN_RENDERED_FALLBACK_TIMEOUT_MS = 2e4;
var firstScreenRendered = false;
var resolveSignal;
var signalPromise = new Promise((resolve) => {
	resolveSignal = resolve;
});
/** 广播「首屏列表已渲染完成」。幂等，只放行一次。模块内部使用（由接收器 / 兜底触发）。 */
function notifyFirstScreenRendered() {
	if (firstScreenRendered) return;
	firstScreenRendered = true;
	resolveSignal?.();
}
var timeoutArmed = false;
function armTimeoutFallback() {
	if (timeoutArmed) return;
	timeoutArmed = true;
	setTimeout(() => notifyFirstScreenRendered(), FIRST_SCREEN_RENDERED_FALLBACK_TIMEOUT_MS).unref?.();
}
/** 等待「首屏列表已渲染完成」信号；首次调用会武装兜底超时，避免永久等待。 */
function whenFirstScreenRendered() {
	if (firstScreenRendered) return Promise.resolve();
	armTimeoutFallback();
	return signalPromise;
}
/**
* 安装 renderer→main 首屏渲染信号接收器：
*   - 注册 ipcMain.handle 收 renderer 的 signalFirstLocalListRendered（幂等）；
*   - 收到后 notifyFirstScreenRendered() 放行 main 侧等待方 + invoke 转发给 daemon 让其门 resolve；
*   - 带 20s 兜底：信号永不到达也强制放行 + 转发一次，daemon 门另有自身 3s 兜底二次保护。
*
* 返回 dispose，用于 bootstrap 收尾释放 ipcMain handler。
*/
function installFirstScreenRenderedReceiver(deps) {
	const ipc = deps.ipc ?? electron.ipcMain;
	const { daemonConnection } = deps;
	let forwarded = false;
	const forwardToDaemon = () => {
		if (forwarded) return;
		forwarded = true;
		daemonConnection.invoke(require_daemon_bootstrap.DAEMON_FIRST_LOCAL_LIST_RENDERED_CHANNEL).catch(() => {
			require_logger.mainLog.warn("[MainBootstrap] forward first-local-list-rendered to daemon failed");
		});
	};
	const trigger = () => {
		notifyFirstScreenRendered();
		forwardToDaemon();
	};
	ipc.removeHandler(require_daemon_bootstrap.RENDERER_FIRST_LOCAL_LIST_RENDERED_CHANNEL);
	ipc.handle(require_daemon_bootstrap.RENDERER_FIRST_LOCAL_LIST_RENDERED_CHANNEL, async () => {
		trigger();
		return { ok: true };
	});
	const fallbackTimer = setTimeout(trigger, FIRST_SCREEN_RENDERED_FALLBACK_TIMEOUT_MS);
	fallbackTimer.unref?.();
	return { dispose: () => {
		clearTimeout(fallbackTimer);
		ipc.removeHandler(require_daemon_bootstrap.RENDERER_FIRST_LOCAL_LIST_RENDERED_CHANNEL);
	} };
}
