//#region src/main/daemon/daemon-credential-bootstrap.ts
async function sendDaemonCredentialProtectionBootstrap(connection, bootstrap) {
	try {
		const result = await connection.invoke(require_credential_protection_bootstrap.DAEMON_CREDENTIAL_PROTECTION_BOOTSTRAP_CHANNEL, require_dist.encodeAtRestEncryptionBootstrap(bootstrap));
		if (!result || typeof result !== "object") return false;
		const ack = result;
		return ack.ok === true && ack.mode === bootstrap.mode;
	} catch {
		return false;
	}
}
