var TIP_SOUND_PLAY_EVENT = "tip-sound:play";
function registerAppServerDesktopHostEvents(connection, desktopHost, options = {}) {
	return connection.onEvent((channel, data) => {
		if (channel === require_server.WORKBUDDY_APP_SERVER_HOST_EVENT_CHANNELS.TASK_COMPLETED_NOTIFICATION) {
			if (!require_server.isWorkbuddyAppServerTaskCompletedNotificationPayload(data)) {
				options.logger?.warn("[DesktopHost] Ignoring invalid task completion notification payload:", data);
				return;
			}
			if (desktopHost.showTaskCompletedNotification(data)) desktopHost.window.send(TIP_SOUND_PLAY_EVENT);
			return;
		}
		if (channel === require_server.WORKBUDDY_APP_SERVER_HOST_EVENT_CHANNELS.TASK_PENDING_NOTIFICATION) {
			if (!require_server.isWorkbuddyAppServerTaskPendingNotificationPayload(data)) {
				options.logger?.warn("[DesktopHost] Ignoring invalid task pending notification payload:", data);
				return;
			}
			if (desktopHost.showTaskPendingNotification(data)) desktopHost.window.send(TIP_SOUND_PLAY_EVENT);
			return;
		}
	});
}
