/**
* daemon 崩溃恢复回调：DaemonAppServerProcessManager 会按
* `onCrash → onReconnecting → onRestored | onGaveUp` 的次序触发。
*
* onGaveUp 承担两件事：
*   1. 调 handleDaemonRecoveryGaveUp（弹窗 + 落盘失败标记 + 诊断上报）
*   2. 注入 monitor 上报通道，让 handler 本身不依赖 monitor 实现（保持关注点分离）
*/
function buildDaemonRecoveryCallbacks() {
	return {
		onCrash: ({ reason, phase }) => {
			require_logger.mainLog.warn(`[MainBootstrap] daemon crash detected (${phase}): ${reason}`);
		},
		onReconnecting: () => {
			require_logger.mainLog.warn("[MainBootstrap] daemon reconnecting (respawn in progress)...");
		},
		onRestored: async (connection) => {
			require_logger.mainLog.info("[MainBootstrap] daemon connection restored after respawn");
			clearDaemonStartupFailureState();
			try {
				await connection.invoke(require_daemon_bootstrap.EXTENSION_ACTIVATE_BY_EVENT_CHANNEL, "onStartup");
				require_logger.mainLog.info("[MainBootstrap] startup extension activation dispatched after daemon respawn");
			} catch (error) {
				require_logger.mainLog.warn("[MainBootstrap] failed to reactivate startup extensions after daemon respawn:", error instanceof Error ? error.message : String(error));
			}
		},
		onGaveUp: ({ reason }) => {
			require_logger.mainLog.error(`[MainBootstrap] daemon recovery gave up: ${reason}`);
			handleDaemonRecoveryGaveUp(reason, { reportGiveUp: (r, coldStartFailures) => {
				require_desktop_monitor_service.DesktopMonitorService.getSharedInstance()?.reportOtelLog({
					timestamp: Date.now(),
					level: "error",
					message: "daemon.recovery.give_up",
					attributes: {
						event: "workbuddy.daemon_give_up",
						reason: r,
						cold_start_failures: String(coldStartFailures)
					}
				}).catch(() => {});
			} });
		}
	};
}
/**
* 从 renderer 旧持久化位置抢救 localStorage 数据，写入临时 JSON 文件供 daemon 读回。
*
* 仅 WorkBuddy 产物需要（其他 SKU 直接跳过），异常降级为 undefined 不阻断启动。
*/
async function prepareLegacyLocalStorageMigrationResultFile(productName, logger) {
	if (productName !== "WorkBuddy") return;
	try {
		const { LocalStorageMigrationService } = await Promise.resolve().then(() => require("./localstorage-migration.js"));
		const result = await new LocalStorageMigrationService().migrate();
		const resultPath = path.join(os.tmpdir().trim(), `workbuddy-localstorage-migration-${process.pid}-${Date.now()}.json`);
		fs.writeFileSync(resultPath, JSON.stringify(result), "utf8");
		return resultPath;
	} catch (error) {
		logger.warn("[MainBootstrap] Failed to prepare legacy localStorage migration input:", error);
		return;
	}
}
/**
* 主进程退出时清理 legacy localStorage migration 临时文件。
*
* 由 bootstrap handle 的 stop() 在关停末段调用；文件不存在或删除失败仅 warn，不抛。
*/
function cleanupLegacyLocalStorageMigrationResultFile(resultPath, logger) {
	if (!resultPath) return;
	try {
		fs.rmSync(resultPath, { force: true });
	} catch (error) {
		logger.warn("[MainBootstrap] Failed to remove legacy localStorage migration input:", error);
	}
}
