//#region src/main/window/security-helpers.ts
/**
* 主进程窗口层通用安全 helper —— 纯函数，无 Electron 副作用。
*
* 用途：URL 协议判定、file:// 转本地路径、CSP 头处理、env 开关识别等。
*/
/** 判断字符串是否表示"启用"的 env 开关值（'1' / 'true'，大小写不敏感）。 */
function isEnabledEnv(value) {
	return value === "1" || value?.toLowerCase() === "true";
}
/**
* 从响应头的 CSP 中仅剥离 frame-ancestors 指令，保留其余指令。
*
* 用于"保留自身 CSP"的第三方/自有 SPA 页面（如知识空间内嵌的 workbuddy.cn CDN 页面）：
* 这些页面需保留自身 script-src 等指令，避免被我们的严格 CSP 覆盖而白屏；
* 但其 CSP 自带的 frame-ancestors 会反过来拒绝被宿主窗口（file:// / app:// / localhost）嵌入。
* 故在保留 CSP 其余部分的同时，仅移除 frame-ancestors。
*/
function stripFrameAncestorsDirective(headers) {
	if (!headers) return headers;
	const result = {};
	for (const [key, values] of Object.entries(headers)) {
		const lower = key.toLowerCase();
		if (lower === "content-security-policy" || lower === "content-security-policy-report-only") {
			const cleaned = values.map((policy) => policy.split(";").filter((directive) => !/^\s*frame-ancestors\b/i.test(directive)).join(";").trim()).filter((policy) => policy.length > 0);
			if (cleaned.length > 0) result[key] = cleaned;
		} else result[key] = values;
	}
	return result;
}
/**
* 若 value 是 file:// URL，转换为本地文件系统路径。
* 非 file URL 或无效输入返回 undefined。
* 处理百分号编码（如中文文件名）以及 Windows 盘符路径（file:///C:/... → C:/...）。
*/
function tryFileUrlToLocalPath(value) {
	if (!value.startsWith("file:")) return;
	try {
		const parsed = new URL(value);
		let pathname = decodeURIComponent(parsed.pathname);
		if (/^\/[A-Za-z]:/.test(pathname)) pathname = pathname.slice(1);
		return pathname;
	} catch {
		return;
	}
}
