//#region src/main/bootstrap/main-bootstrap.ts
require_app_instance.init_app_instance();
/**
* 主进程启动编排入口。
*
* 三件事：
*   1. `setupStartupLifecycle`：装配唯一真相源（状态机 + logger + context + markStartup 桥）
*   2. 声明式装配 `StartupPipeline`：注册启动 stage（当前是大颗粒的 core / daemon-and-post 两个 Step），
*      顺序与降级策略由 Pipeline 施加统一护栏；具体动作沉在各 Step 内部。
*   3. `createMainBootstrapHandle`：装配返回给 index.ts 的 handle（RPC 转发方法 + stop 关停闭包）；
*      stop 里会一并 dispose lifecycle 装配层。
*
* 打点 B1 落在 pipeline.run() 之前（Phase B 的入口边界打点）；其余 B* 打点跟随代码搬入了各 Step 内部。
* lifecycle 状态机的 phase-enter / state 迁移由 mark-bridge 从 markStartup 反向观察发出，
* Pipeline 的 phase 事件不直接驱动生产语义，只提供未来把细粒度 Step 逐个迁入时的编排承载。
*/
async function bootstrapMainProcess(resolveBootstrapDeferred, onHistoryProgress, options = {}, onRepairProgress) {
	const t0 = Date.now();
	const elapsed = () => `+${Date.now() - t0}ms`;
	const bsLog = createStartupDiagnosticLog(elapsed);
	const evalModeEnabled = false;
	const credentialProtectionBootstrap = options.credentialProtectionBootstrap ?? require_dist.createUnavailableAtRestEncryptionBootstrap("disabled", "missing-key");
	bsLog("bootstrapMainProcess entered");
	require_menu_builder.markStartup("B1");
	const { pipeline, lifecycle, disposeStartupLifecycle } = setupStartupLifecycle(bsLog);
	lifecycle.onStuck(9e4, (stuckState) => {
		bsLog(`onStuck fired at state=${stuckState}, forcing failed`);
		lifecycle.markFailed(`stuck at ${stuckState}`);
	});
	const handleDepsRef = {};
	pipeline.registerAll([
		createPlatformStep({ bsLog }),
		createWindowManagerStep({ onWindowManagerReady: options.onWindowManagerReady }),
		registerDesktopHostIpcStep(),
		installWbInvokeStep(),
		ensureMainWindowStep(),
		createDatabaseStep({
			evalModeEnabled,
			bsLog
		}),
		initCellJSContainerStep({
			evalModeEnabled,
			elapsed,
			bsLog
		}),
		bindDaemonProvidersStep(),
		resolveCellDepsStep({
			evalModeEnabled,
			bsLog
		}),
		setupAuthAndSidecarStep({ credentialProtectionBootstrap }),
		startCrashExporterStep({ bsLog }),
		initializeDatabaseStep({
			onRepairProgress,
			bsLog
		}),
		createMonitorServiceStep(),
		runStartupMigrationStep({
			evalModeEnabled,
			onHistoryProgress,
			elapsed,
			bsLog
		}),
		mergeFallbackAndRepairStep({
			evalModeEnabled,
			onHistoryProgress,
			bsLog
		}),
		prepareDaemonContextStep({
			elapsed,
			bsLog
		}),
		selectDaemonRuntimeStep({
			evalModeEnabled,
			crashWriterHandle: options.crashWriterHandle,
			credentialProtectionBootstrap
		}),
		wireDaemonBridgesStep({
			resolveBootstrapDeferred,
			onHistoryProgress,
			evalModeEnabled,
			bsLog
		}),
		wireWbInvokeStep(),
		createDesktopDaemonStateStep(),
		registerDesktopHostRpcStep(),
		startAppServerBackgroundStep({ evalModeEnabled }),
		schedulePostDaemonTasksStep({
			evalModeEnabled,
			bsLog
		}),
		registerSelfCheckStep(),
		prefetchTuringDeviceTokenStep(),
		reconcileAutoLaunchStep(),
		repairDockRecentAppsStep(),
		assembleHandleDepsStep({ out: handleDepsRef })
	]);
	await pipeline.run();
	if (!handleDepsRef.current) throw new Error("[MainBootstrap] pipeline completed but assemble-handle-deps did not produce handle");
	return createMainBootstrapHandle({
		...handleDepsRef.current,
		startupLifecycle: lifecycle,
		disposeStartupLifecycle
	});
}
/**
* 装配启动生命周期真相源：状态机 + logger + context + markStartup → phase/state 双写桥。
*
* 说明：本项目 lifecycle 目录下的 pipeline / context / mark-bridge 已经就位，此函数是它们
* 唯一的生产装配点。返回值：
*   - `pipeline`：供上层注册 Step 并 run()
*   - `disposeStartupLifecycle`：卸载 mark-bridge 观察者（stop 时调用，避免异步 emit 到已 dispose 的 lifecycle）
*/
function setupStartupLifecycle(bsLog) {
	const logger = createStartupLogger((level, message) => {
		if (level === "error") require_logger.mainLog.error(message);
		else if (level === "warn") require_logger.mainLog.warn(message);
		else require_logger.mainLog.info(message);
		bsLog(message);
	});
	const lifecycle = new StartupLifecycle(logger);
	const ctx = createStartupContext(lifecycle, logger);
	const disposeMarkBridge = installStartupMarkBridge(lifecycle);
	return {
		pipeline: new StartupPipeline({
			lifecycle,
			ctx,
			stepDurationObserver: (info) => {
				require_desktop_monitor_service.DesktopMonitorService.getSharedInstance()?.recordDuration(`startup.step.${info.phase}.${info.stepId}`, info.durationMs, { status: info.status });
			}
		}),
		lifecycle,
		disposeStartupLifecycle: disposeMarkBridge
	};
}
/**
* 从 ctx 拿全部 daemon phase 产出，组装 createMainBootstrapHandle 所需的 deps。
*
* 这一步没有实际动作，只是把 typed capability 汇总成 handle deps 的形状——所有具体装配
* 都已经在前面独立 Step 里完成了。dependsOn 声明本 Step 排在最后一个 DaemonBringup Step
* （schedule-post-daemon-tasks）之后。
*/
function assembleHandleDepsStep(deps) {
	return {
		id: "main.assemble-handle-deps",
		phase: StartupPhase.PostReady,
		critical: false,
		dependsOn: ["daemon.schedule-post-daemon-tasks"],
		async run(ctx) {
			const windowManager = ctx.requireWindow();
			const disposeEarlyDesktopHostIpc = ctx.requireCapability(BOOT_DISPOSE_EARLY_DESKTOP_HOST_IPC);
			const runtime = ctx.requireCapability(BOOT_DAEMON_RUNTIME);
			const bridgeDisposers = ctx.requireCapability(BOOT_BRIDGE_DISPOSERS);
			const auth = ctx.requireCapability(BOOT_AUTH);
			const monitor = ctx.requireCapability(BOOT_MONITOR);
			const localProbeServer = ctx.requireCapability(BOOT_LOCAL_PROBE_SERVER);
			const database = ctx.requireCapability(BOOT_DATABASE);
			const tencentBridge = ctx.requireCapability(BOOT_TENCENT_BRIDGE);
			const { desktopDaemonState, disposeAuthLifecycle, disposeDocsAiEditFeatureCache, disposeGalileoConfigBridge, disposeSeedConfigBridge } = ctx.requireCapability(BOOT_DESKTOP_DAEMON_STATE);
			const { daemonSessionQueries, disposeDesktopHostIpc } = ctx.requireCapability(BOOT_DESKTOP_HOST_RPC);
			const { mcpAppsHost, backgroundPromise, disposeMainRuntimeHandlers } = ctx.requireCapability(BOOT_APP_SERVER_BACKGROUND);
			const evalProxyServer = ctx.requireCapability(BOOT_EVAL_PROXY_SERVER);
			const { migrationDonePromise, healthCheckTimer, disposeTencentDocsSelectionBroadcast, disposeTencentDocsPrewarmScheduler, disposeFirstScreenRenderedReceiver } = ctx.requireCapability(BOOT_POST_DAEMON_TASKS);
			deps.out.current = {
				windowManager,
				disposeEarlyDesktopHostIpc,
				daemonConnection: runtime.daemonConnection,
				daemonSessionQueries,
				migrationDonePromise,
				ideLifecycle: auth.ideLifecycle,
				monitorService: monitor.monitorService,
				localProbeServer,
				desktopDaemonState,
				daemon: runtime.daemon,
				daemonProcess: runtime.daemonProcess,
				database,
				evalProxyServer,
				mcpAppsHost,
				backgroundPromise,
				healthCheckTimer,
				disposeAuthLifecycle,
				disposeDocsAiEditFeatureCache,
				disposeGalileoConfigBridge,
				disposeSeedConfigBridge,
				disposeMainRuntimeHandlers,
				disposeRemoteMigrationProgress: bridgeDisposers.disposeRemoteMigrationProgress,
				disposeTencentDocsDaemonRendererEvents: bridgeDisposers.disposeTencentDocsDaemonRendererEvents,
				disposeTencentDocsLocalPreviewLocaleSync: bridgeDisposers.disposeTencentDocsLocalPreviewLocaleSync,
				disposeAppServerDesktopHostBridge: runtime.disposeAppServerDesktopHostBridge,
				disposeAppServerDesktopHostEvents: bridgeDisposers.disposeAppServerDesktopHostEvents,
				disposeAppServerPowerEventBridge: bridgeDisposers.disposeAppServerPowerEventBridge,
				disposeLocalStorageMigrationCompletion: bridgeDisposers.disposeLocalStorageMigrationCompletion,
				disposeTencentDocsSelectionBroadcast,
				disposeTencentDocsPrewarmScheduler,
				disposeFirstScreenRenderedReceiver,
				disposeTencentDocsRendererEventBridgeIpc: tencentBridge.dispose,
				disposeDesktopHostIpc,
				legacyLocalStorageMigrationResultPath: runtime.legacyLocalStorageMigrationResultPath,
				cleanupLegacyLocalStorageMigrationResultFile
			};
		}
	};
}
/**
* 客户端自检工具 IPC handler 注册 step。
*
* 在 daemon 连接就绪后注册自检 handler，使 renderer 可通过 RPC 调用。
* 非致命：注册失败仅 warn，不阻断启动。
*/
function registerSelfCheckStep() {
	return {
		id: "main.register-self-check",
		phase: StartupPhase.PostReady,
		critical: false,
		dependsOn: ["daemon.schedule-post-daemon-tasks"],
		async run(ctx) {
			const daemonConnection = ctx.requireCapability(BOOT_DAEMON_RUNTIME).daemonConnection;
			const { desktopDaemonState } = ctx.requireCapability(BOOT_DESKTOP_DAEMON_STATE);
			const getAuthSession = () => desktopDaemonState.getSession();
			try {
				const { createSelfCheckController, registerSelfCheckHandlers, getReportMeta, getShowFull } = await Promise.resolve().then(() => require("./self-check.js"));
				const { dialog, shell, app } = await import("electron");
				const selfCheckController = createSelfCheckController({
					clientVersion: app.getVersion(),
					isPackaged: app.isPackaged,
					networkRunner: { async runDiagnostics() {
						return daemonConnection.invoke("runNetworkDiagnostics");
					} },
					getAuthSession,
					getAppMetrics: () => app.getAppMetrics()
				});
				const selfCheckReportDir = require_workbuddy_paths.getWorkbuddyLogsDir("diagnostics");
				require_logger.mainLog.info(`[MainBootstrap] Self-check showFull=${getShowFull(getAuthSession)} reportDir=${selfCheckReportDir}`);
				registerSelfCheckHandlers(daemonConnection, {
					controller: selfCheckController,
					reportDir: selfCheckReportDir,
					dialog: { showSaveDialog: (opts) => dialog.showSaveDialog(opts) },
					shell: {
						openPath: async (p) => {
							await shell.openPath(p);
						},
						showItemInFolder: (fp) => shell.showItemInFolder(fp)
					},
					getReportMeta: async () => getReportMeta(app.getVersion()),
					getShowFull: () => getShowFull(getAuthSession),
					broadcast: (channel, data) => {
						const { BrowserWindow } = require("electron");
						for (const win of BrowserWindow.getAllWindows()) if (!win.isDestroyed()) win.webContents.send(channel, data);
					}
				});
				require_logger.mainLog.info("[MainBootstrap] Self-check handlers registered");
			} catch (err) {
				require_logger.mainLog.warn(`[MainBootstrap] Self-check setup failed (non-fatal): ${err instanceof Error ? err.message : String(err)}`);
			}
		}
	};
}
/**
* 与 index.ts 共享的 startup 诊断日志：每次 bsLog(...) 追加一行到
* `<configDir>/logs/startup/startup-<date>.log`，写失败静默不阻断启动。
*/
function createStartupDiagnosticLog(elapsed) {
	const logDir = require_workbuddy_paths.getWorkbuddyLogsDir("startup");
	const logDate = (/* @__PURE__ */ new Date()).toISOString().slice(0, 10);
	const logFile = path.join(logDir, `startup-${logDate}.log`);
	return (msg) => {
		const line = `[${(/* @__PURE__ */ new Date()).toISOString()}] [bootstrap ${elapsed()}] ${msg}\n`;
		try {
			fs.appendFileSync(logFile, line);
		} catch (err) {
			require_logger.mainLog.warn("[MainBootstrap] startup diagnostic log append failed", err);
		}
	};
}
