//#region src/main/credential-protection/main-bootstrap.ts
function loadMainCredentialProtectionBootstrap(mode, getKey) {
	try {
		return {
			mode,
			symmetricKey: require_dist.normalizeAtRestKeyPayload(getKey()),
			asymmetricUnavailable: "missing-key"
		};
	} catch {
		return {
			mode,
			symmetricUnavailable: "invalid-key",
			asymmetricUnavailable: "missing-key"
		};
	}
}
