/**
* 解压 vendor 资源。整个过程不会 throw：解压失败仅 warn，让 bootstrap 继续走
* fallback 路径（系统 Git 兜底）。首次启动约 30–90s；后续启动通过 .extracted
* 标记快速跳过（<50ms）。
*/
async function ensureVendorAssets(deps) {
	if (VENDOR_ASSETS.length === 0) return;
	const phaseStart = Date.now();
	deps.log(`Phase: vendor extract check, assetsCount=${VENDOR_ASSETS.length}`);
	const checkStart = Date.now();
	const extractNeeded = VendorExtractService.isExtractNeeded(deps.resourcesPath, VENDOR_ASSETS);
	deps.log(`Phase: vendor isExtractNeeded=${extractNeeded} (checkMs=${Date.now() - checkStart})`);
	if (extractNeeded) {
		deps.onSplashUpdate({
			phase: "initializing",
			caption: deps.splashMessages.caption
		});
		await deps.onNeedsSplash();
		deps.log("Phase: showSplashIfNeeded returned OK");
	}
	try {
		deps.log("Phase: vendor ensureAll starting");
		const ensureStart = Date.now();
		const vendorResults = await VendorExtractService.ensureAll(deps.resourcesPath, VENDOR_ASSETS);
		const ensureElapsed = Date.now() - ensureStart;
		const resultSummary = vendorResults.map((r) => {
			if (!r.success) return `${r.name}:failed`;
			return r.skipped ? `${r.name}:skipped` : `${r.name}:extracted`;
		}).join(",");
		deps.log(`Phase: vendor ensureAll done (elapsed=${ensureElapsed}ms), results=${resultSummary}`);
		for (const r of vendorResults) if (!r.success) {
			deps.warnLog(`[Vendor] ${r.name} failed: ${r.error}`);
			if (r.name === "PortableGit") {
				const envCleared = clearStaleGitBashEnv("ensureAll-failed");
				const currentEnv = process.env.CODEBUDDY_CODE_GIT_BASH_PATH?.trim();
				deps.warnLog(`[Vendor] critical=PortableGit envCleared=${envCleared} currentEnvValid=${isExistingFile(currentEnv)} currentEnv=${currentEnv || "NOT_SET"}`);
			}
		}
		const failed = vendorResults.filter((r) => !r.success).length;
		deps.infoLog(`[Vendor] Done: total=${vendorResults.length}, failed=${failed}`);
	} catch (err) {
		deps.log(`Phase: vendor ensureAll threw: ${err instanceof Error ? err.message : String(err)}`);
		deps.warnLog("[Vendor] Extract error (non-fatal):", err);
	}
	deps.log(`Phase: vendor extract phase complete (totalElapsed=${Date.now() - phaseStart}ms)`);
}
