//#region src/main/system/runtime/post-ready-hooks.ts
/**
* 执行 whenReady 入口一次性 hooks：quarantine 清除 → legacy protocol 清理 → dock icon 修正。
*
* ## 各段作用
*
* ### darwin quarantine 清除
* Squirrel.Mac 自更新路径：新包由系统 `open` 启动，quarantine 属性可能未被系统自动
* 清除。启动后主动检测并清掉，避免下次冷启动时 Gatekeeper 误判"已损坏"直接拒启。
* 打包版才有意义（dev 模式的 Electron 二进制没有 quarantine 属性）。
*
* ### legacy protocol 清理
* 清除历史版本注册过的 protocol handler，避免同一个 workbuddy://（或类似 scheme）
* 被两个版本抢占导致 deep link 走到旧进程。跨平台通用，无副作用检查。
*
* ### darwin dock icon（仅 dev 模式）
* Electron dev 模式下 Dock 显示紫色 Electron 占位图标，需手动 setIcon 覆盖。
* **打包模式下反而不能设** —— `.app/Contents/Resources/icon.icns` 已被 macOS 从
* CFBundleIconFile 读到，运行时 setIcon 会用一张低保真 `dist/resources/icon.png`
* 覆盖它，导致定制版启动时是定制图标、启动后变回默认图标（issue #36168）。
*/
async function runPostReadyPlatformHooks(deps) {
	if (deps.platform === "darwin" && deps.isPackaged) {
		const appPath = deps.execPath.split("/Contents/")[0];
		if (appPath.endsWith(".app")) deps.execFileAsync("/usr/bin/xattr", ["-l", appPath]).then(({ stdout }) => {
			if (stdout.includes("com.apple.quarantine")) return deps.execFileAsync("/usr/bin/xattr", [
				"-dr",
				"com.apple.quarantine",
				appPath
			]).then(() => {
				deps.infoLog("darwin: quarantine cleared on first launch");
			});
		}).catch(() => {});
	}
	deps.removeLegacyProtocolRegistrations();
	if (deps.platform === "darwin" && !deps.isPackaged) try {
		const { app, nativeImage } = await deps.getElectron();
		if (!app.dock) return;
		const iconPath = deps.resolveBundledAsset("resources", "icon.png");
		if (!iconPath) return;
		try {
			const icon = nativeImage.createFromPath(iconPath);
			if (!icon.isEmpty()) app.dock.setIcon(icon);
		} catch {}
	} catch (err) {
		deps.warnLog?.("[WorkBuddy] dev-mode dock icon setup failed:", err);
	}
}
/**
* 调度 bootstrap 后台清理任务。fire-and-forget，异常吞掉。
*/
function schedulePostBootstrapBackgroundTasks(deps) {
	const platform = deps.platform ?? process.platform;
	const scheduleProbe = () => {
		(deps.loadSafeStorageStartupProbe ?? (() => Promise.resolve().then(() => require("./safe-storage-startup-probe.js"))))().then(({ scheduleSafeStorageStartupProbe }) => scheduleSafeStorageStartupProbe(true)).catch((error) => {
			require_logger.mainLog.warn("[SafeStorageProbe] probe module load failed", error);
		});
	};
	whenSafeStorageStartupProbeEnabled(platform, scheduleProbe);
	const delayMs = deps.delayMs ?? 1e4;
	(deps.setTimeoutImpl ?? setTimeout)(() => {
		deps.cleanupLiteSandboxLegacy().catch(() => {});
		deps.cleanupOldRepairHelperLogs?.().catch(() => {});
	}, delayMs);
}
