//#region src/main/window/splash-progress-watchdog.ts
var DEFAULT_TIMERS = {
	setTimeout: (handler, ms) => setTimeout(handler, ms),
	clearTimeout: (handle) => clearTimeout(handle),
	now: () => Date.now()
};
/**
* 创建一个「无进展」看门狗。
* @param getLastProgressAt 返回最近一次进展的时间戳（ms），由进度回调刷新。
*/
function createSplashProgressWatchdog(getLastProgressAt, options) {
	const timers = options.timers ?? DEFAULT_TIMERS;
	const pollMs = options.pollMs ?? 5e3;
	const startedAt = timers.now();
	let settled = false;
	let handle = null;
	let resolveFn;
	const promise = new Promise((resolve) => {
		resolveFn = resolve;
	});
	const stop = () => {
		if (handle) {
			timers.clearTimeout(handle);
			handle = null;
		}
	};
	const tick = () => {
		if (settled) return;
		const now = timers.now();
		if (now - startedAt >= options.absoluteMs) {
			settled = true;
			stop();
			resolveFn("absolute-timeout");
			return;
		}
		if (now - getLastProgressAt() >= options.idleMs) {
			settled = true;
			stop();
			resolveFn("idle-timeout");
			return;
		}
		handle = timers.setTimeout(tick, pollMs);
		handle.unref?.();
	};
	handle = timers.setTimeout(tick, pollMs);
	handle.unref?.();
	return {
		promise,
		cancel() {
			settled = true;
			stop();
		}
	};
}
